// ExternalRef identifies an external agent binary found on $PATH by filename
// alone — no "info" subcommand is executed to produce it. Name is derived from
// the "entire-agent-<name>" filename; BinaryPath is the resolved path.
type ExternalRef struct {
	Name       types.AgentName
	BinaryPath string
}

// WalkExternalBinaries scans $PATH for "entire-agent-*" executables and returns
// one ExternalRef per distinct agent name WITHOUT executing any binary. Names
// conflicting with an already-registered (built-in) agent are skipped, as are
// directories and non-executable files. Deduplicated by binary filename and by
// derived name (first match on $PATH wins), returned in sorted name order.
//
// This is the cheap discovery path for read-only listings: the caller learns
// every external's name and location for roughly one $PATH glob (~15ms for a
// large PATH), instead of paying an "info" exec per plugin (~100ms+ each).
func WalkExternalBinaries(ctx context.Context) []ExternalRef {
	discoveryCtx, cancel := context.WithTimeout(ctx, discoveryTimeout)
	defer cancel()

	pathEnv := os.Getenv("PATH")
	if pathEnv == "" {
		return nil
	}

	// Collect already-registered names to avoid conflicts with built-ins.
	registered := make(map[types.AgentName]bool)
	for _, name := range agent.List() {
		registered[name] = true
	}

	seenBinary := make(map[string]bool)          // dedup by filename across PATH dirs
	seenName := make(map[types.AgentName]bool)    // dedup exe-ext variants of one name
	var refs []ExternalRef
	for _, dir := range filepath.SplitList(pathEnv) {
		if discoveryCanceled(ctx, discoveryCtx) {
			logging.Debug(ctx, "external agent discovery timed out")
			break
		}

		matches, err := filepath.Glob(filepath.Join(dir, binaryPrefix+"*"))
		if err != nil {
			continue // skip unreadable directories
		}
		for _, binPath := range matches {
			base := filepath.Base(binPath)
			if seenBinary[base] {
				continue
			}
			seenBinary[base] = true

			// Strip Windows executable extensions (.exe, .bat) before deriving agent name.
			// On Unix, binaries have no extension, so this is a no-op.
			cleanName := StripExeExt(base)
			agentName := types.AgentName(strings.TrimPrefix(cleanName, binaryPrefix))
			if registered[agentName] {
				logging.Debug(ctx, "skipping external agent (name conflict with built-in)",
					slog.String("binary", base),
					slog.String("agent", string(agentName)))
				continue
			}
			if seenName[agentName] {
				continue
			}
			if !isExecutableFile(binPath) {
				continue
			}
			seenName[agentName] = true
			refs = append(refs, ExternalRef{Name: agentName, BinaryPath: binPath})
		}
	}

	slices.SortFunc(refs, func(a, b ExternalRef) int {
		return strings.Compare(string(a.Name), string(b.Name))
	})
	return refs
}

// isExecutableFile reports whether binPath is a regular, executable file. On
// Windows the execute bit is not meaningful, so only the not-a-directory check
// applies. Mirrors the validity checks in registerExternalAgent, but stats only
// — it never executes the binary.
func isExecutableFile(binPath string) bool {
	finfo, err := statExternalAgent(binPath)
	if err != nil || finfo.IsDir() {
		return false
	}
	if runtime.GOOS != osWindows && finfo.Mode()&0o111 == 0 {
		return false
	}
	return true
}

// HooksInstalled reports whether the external binary at binPath has its hooks
// installed, by executing only its "are-hooks-installed" subcommand. Unlike
// New, it does NOT call "info": install-state does not depend on the cached
// metadata, so a read-only listing can probe it without the identity exec.
func HooksInstalled(ctx context.Context, binPath string) bool {
	return (&Agent{binaryPath: binPath}).AreHooksInstalled(ctx)
}

