func runAgentList(ctx context.Context, w io.Writer, externalOnly bool) error {
	hasSomeInstalled := false
	printAgent := func(name string, installed, isExternal bool) {
		marker := "  "
		if installed {
			marker = "✓ "
			hasSomeInstalled = true
		}
		suffix := ""
		if isExternal {
			suffix = " (external)"
		}
		fmt.Fprintf(w, "  %s%s%s\n", marker, name, suffix)
	}

	// --external is the explicit opt-in to the costly path: scan $PATH for
	// external agent plugins (one are-hooks-installed exec per plugin) and list
	// them, installed or not. Kept behind a flag so the default listing never
	// pays this — see the plain path below.
	if externalOnly {
		fmt.Fprintln(w, "External agents:")
		refs := external.WalkExternalBinaries(ctx)
		for _, ref := range refs {
			printAgent(string(ref.Name), external.HooksInstalled(ctx, ref.BinaryPath), true)
		}
		if len(refs) == 0 {
			fmt.Fprintln(w, "\nNo external agent plugins found on your PATH.")
		} else if !hasSomeInstalled {
			fmt.Fprintln(w, "\nNo external agents installed. Use 'entire agent add <name>' to install hooks.")
		}
		return nil
	}

	// Default: built-in agents only — enumerated from the registry with no PATH
	// scan and no plugin exec, so the listing stays fast regardless of how many
	// external plugins are on $PATH.
	fmt.Fprintln(w, "Agents:")
	for _, name := range agent.List() {
		ag, err := agent.Get(name)
		if err != nil {
			logging.Debug(ctx, "agent registered but unresolvable, skipping",
				slog.String("agent", string(name)), slog.String("error", err.Error()))
			continue
		}
		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
			continue
		}
		if external.IsExternal(ag) {
			continue // externals are listed via --external, not here
		}
		installed := false
		if hs, ok := agent.AsHookSupport(ag); ok && hs.AreHooksInstalled(ctx) {
			installed = true
		}
		printAgent(string(name), installed, false)
	}

	if !hasSomeInstalled {
		fmt.Fprintln(w, "\nNo agents installed. Use 'entire agent add <name>' to install hooks.")
	}
	fmt.Fprintln(w, "\nRun 'entire agent list --external' to list external agent plugins on your PATH.")

