167	// This is the cheap discovery path for read-only listings: the caller learns
168	// every external's name and location for roughly one $PATH glob (~15ms for a
169	// large PATH), instead of paying an "info" exec per plugin (~100ms+ each).
170	func WalkExternalBinaries(ctx context.Context) []ExternalRef {
171		discoveryCtx, cancel := context.WithTimeout(ctx, discoveryTimeout)
172		defer cancel()
173	
174		pathEnv := os.Getenv("PATH")
175		if pathEnv == "" {
176			return nil
177		}
178	
179		// Collect already-registered names to avoid conflicts with built-ins.
180		registered := make(map[types.AgentName]bool)
181		for _, name := range agent.List() {
182			registered[name] = true
183		}
184	
185		seenBinary := make(map[string]bool)        // dedup by filename across PATH dirs
186		seenName := make(map[types.AgentName]bool) // dedup exe-ext variants of one name
187		var refs []ExternalRef
188		for _, dir := range filepath.SplitList(pathEnv) {
189			if discoveryCanceled(ctx, discoveryCtx) {
190				logging.Debug(ctx, "external agent discovery timed out")
191				break
192			}
